# Calculate mass loss in 200-450 C range for the current sheet
diff = np.interp(200, x, y1) - np.interp(450, x, y1)
# Find the index of the current sheet in the global sheets list to update its name
if 'sheet' in globals() and isinstance(sheet, str):
    try:
        # Assuming 'names' is a mutable list accessible in the global scope of the sandbox
        if 'names' in globals():
            idx = names.index(sheet)
            names[idx] = f"{sheet} (Δm: {diff:.2f} wt%)"
